    const presentation=new Set(['achievements_menu','card_view','codex_menu','hud','loading','main_menu',
      'pile_viewer','rest_overlay','reward_overlay','shop','shop_item','starter_select','xp_screen']
      .map(name=>'scripts/'+name+'.gdc'));
    // A casino caption can describe a payout calculated in a different script.
    const scriptKey=p=>p.replace(/\.gd\.remap$/,'.gdc');
    const casinoPart=p=>p.startsWith('scripts/casino/') || ['scripts/game.gdc','scripts/event_screen.gdc',
      'scripts/reward_overlay.gdc','scenes/event.tscn.remap'].includes(p);
